1	import { readFile, writeFile } from 'node:fs/promises'
2	import { join } from 'node:path'
3	import { PLAN_DIR, featureSlug } from './blind-plan'
4	import type { SpecState } from './spec-file'
5	
6	/**
7	 * A review of a draft plan artifact: the human's comments and strikes, the
8	 * agent's resolutions. It lives next to the spec as markdown so it survives a
9	 * reload, stays readable after approval, and can be written to by the agent
10	 * with the same tools it uses on the spec.
11	 */
12	
13	export type ResolutionKind = 'addressed' | 'disagreed'
14	
15	export type Resolution = { kind: ResolutionKind; text: string }
16	
17	/** Target of a comment on the artifact as a whole rather than on an item. */
18	export const PLAN_TARGET = 'plan'
19	
20	export type ReviewComment = {
21	  /** C1, C2, ... stable once the round is submitted. */
22	  id: string
23	  /** An item id (B3, T1, F2) or `plan` for the artifact as a whole. */
24	  target: string
25	  text: string
26	  /** The item's text when the comment was written; carried to the agent when the id is gone (E5). */
27	  item?: string
28	  /** Written by the agent when it revises; every comment gets one (B6). */
29	  resolution?: Resolution
30	  /** The human accepted the resolution. An unaccepted comment is open and blocks approval (B8, B10). */
31	  closed?: boolean
32	}
33	
34	export type ReviewRound = {
35	  number: number
36	  /** ISO timestamp of submission; absent while the round is still being written. */
37	  submittedAt?: string
38	  comments: ReviewComment[]
39	  /** Ids of items the human wants gone (B2). */
40	  strikes: string[]
41	}
42	
43	export type Review = { rounds: ReviewRound[] }
44	
45	/** One item of the artifact, addressed by its id. */
46	export type PlanItem = {
47	  id: string
48	  /** The line's text after the id, as written. */
49	  text: string
50	  /** Section heading the item sits under, for display. */
51	  section: string
52	  /** The artifact says the item is gone (B5). */
53	  removed: boolean
54	}
55	
56	export const emptyReview = (): Review => ({ rounds: [] })
57	
58	export function reviewPath(cwd: string, feature: string): string {
59	  return join(cwd, PLAN_DIR, `${featureSlug(feature)}.review.md`)
60	}
61	
62	/** Workspace-relative path of the review file, the form used in prompts and scopes. */
63	export function reviewFile(feature: string): string {
64	  return `${PLAN_DIR}/${featureSlug(feature)}.review.md`
65	}
66	
67	const ITEM = /^-\s+([A-Z]{1,3}\d+)\b\s*(?:\(([^)]*)\))?\s*:\s*(.*)$/
68	const REMOVED = /\[removed\]/i
69	const HEADING = /^#{1,6}\s+(.*)$/
70	
71	/** The artifact's items, in file order, with the section they sit under. */
72	export function planItems(body: string): PlanItem[] {
73	  const items: PlanItem[] = []
74	  let section = ''
75	  for (const line of body.split(/\r?\n/)) {
76	    const heading = HEADING.exec(line.trim())
77	    if (heading) {
78	      section = heading[1]!.trim()
79	      continue
80	    }
81	    const match = ITEM.exec(line.trim())
82	    if (!match) continue
83	    items.push({
84	      id: match[1]!,
85	      text: (match[2] ? `(${match[2]}) ` : '') + match[3]!.trim(),
86	      section,
87	      removed: REMOVED.test(line),
88	    })
89	  }
90	  return items
91	}
92	
93	export function findItem(body: string, id: string): PlanItem | undefined {
94	  return planItems(body).find((i) => i.id === id)
95	}
96	
97	/** Commenting is offered on a draft only; an approved plan is reopened or superseded (B12). */
98	export function isCommentable(state: SpecState): boolean {
99	  return state.exists && state.status === 'draft'
100	}
101	
102	export function assertCommentable(state: SpecState): void {
103	  if (!state.exists) throw new Error('No plan to comment on yet.')
104	  if (state.status !== 'draft') throw new Error('An approved plan is not commentable: reopen or supersede it.')
105	}
106	
107	// --- reading and writing -----------------------------------------------------
108	
109	const ROUND = /^##\s+Round\s+(\d+)\b(.*)$/
110	const SUBMITTED = /submitted\s+(\S+)/i
111	const COMMENT = /^-\s+(C\d+)\s*\(([^)]*)\)\s*:\s*(.*)$/
112	const STRUCK = /^-\s+struck\s*:\s*(.*)$/i
113	const CHILD = /^\s+-\s+(.*)$/
114	const RESOLUTION = /^(?:resolution\s*)?\(?(addressed|disagreed)\)?\s*:\s*(.*)$/i
115	const ITEM_TEXT = /^item\s*:\s*(.*)$/i
116	const ACCEPTED = /^accepted\b/i
117	
118	export function parseReview(text: string): Review {
119	  const review: Review = { rounds: [] }
120	  let round: ReviewRound | undefined
121	  let comment: ReviewComment | undefined
122	  for (const raw of text.split(/\r?\n/)) {
123	    const line = raw.trimEnd()
124	    const roundMatch = ROUND.exec(line.trim())
125	    if (roundMatch) {
126	      const submitted = SUBMITTED.exec(roundMatch[2] ?? '')
127	      round = {
128	        number: Number(roundMatch[1]),
129	        ...(submitted ? { submittedAt: submitted[1]! } : {}),
130	        comments: [],
131	        strikes: [],
132	      }
133	      comment = undefined
134	      review.rounds.push(round)
135	      continue
136	    }
137	    if (!round) continue
138	    const child = CHILD.exec(line)
139	    if (child && comment) {
140	      const body = child[1]!.trim()
141	      const resolution = RESOLUTION.exec(body)
142	      if (resolution) {
143	        comment.resolution = { kind: resolution[1]!.toLowerCase() as ResolutionKind, text: resolution[2]!.trim() }
144	        continue
145	      }
146	      const item = ITEM_TEXT.exec(body)
147	      if (item) {
148	        comment.item = item[1]!.trim()
149	        continue
150	      }
151	      if (ACCEPTED.test(body)) comment.closed = true
152	      continue
153	    }
154	    const trimmed = line.trim()
155	    const struck = STRUCK.exec(trimmed)
156	    if (struck) {
157	      round.strikes = struck[1]!
158	        .split(',')
159	        .map((s) => s.trim())
160	        .filter((s) => s.length > 0)
161	      comment = undefined
162	      continue
163	    }
164	    const commentMatch = COMMENT.exec(trimmed)
165	    if (commentMatch) {
166	      comment = { id: commentMatch[1]!, target: commentMatch[2]!.trim(), text: commentMatch[3]!.trim() }
167	      round.comments.push(comment)
168	      continue
169	    }
170	    if (trimmed.length > 0) comment = undefined
171	  }
172	  return review
173	}
174	
175	export function renderReview(review: Review, title: string): string {
176	  const lines = [
177	    `# Review of ${title}`,
178	    '',
179	    'Comments and strikes are the human\u2019s; resolutions are the agent\u2019s. A submitted comment keeps its id.',
180	  ]
181	  for (const round of review.rounds) {
182	    lines.push('', `## Round ${round.number}${round.submittedAt ? ` — submitted ${round.submittedAt}` : ' — pending'}`)
183	    for (const comment of round.comments) {
184	      lines.push(`- ${comment.id} (${comment.target}): ${comment.text}`)
185	      if (comment.item) lines.push(`  - item: ${comment.item}`)
186	      if (comment.resolution) lines.push(`  - ${comment.resolution.kind}: ${comment.resolution.text}`)
187	      if (comment.closed) lines.push('  - accepted')
188	    }
189	    if (round.strikes.length > 0) lines.push(`- struck: ${round.strikes.join(', ')}`)
190	  }
191	  return lines.join('\n') + '\n'
192	}
193	
194	export async function readReview(path: string): Promise<Review> {
195	  try {
196	    return parseReview(await readFile(path, 'utf8'))
197	  } catch (error) {
198	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return emptyReview()
199	    throw error
200	  }
201	}
202	
203	export async function writeReview(path: string, review: Review, title: string): Promise<void> {
204	  await writeFile(path, renderReview(review, title), 'utf8')
205	}
206	
207	// --- authoring ---------------------------------------------------------------
208	
209	/** The round being written, if any; a submitted review has none until the human comments again. */
210	export function pendingRound(review: Review): ReviewRound | undefined {
211	  const last = review.rounds.at(-1)
212	  return last && last.submittedAt === undefined ? last : undefined
213	}
214	
215	function openRound(review: Review): ReviewRound {
216	  const existing = pendingRound(review)
217	  if (existing) return existing
218	  const round: ReviewRound = { number: (review.rounds.at(-1)?.number ?? 0) + 1, comments: [], strikes: [] }
219	  review.rounds.push(round)
220	  return round
221	}
222	
223	function allComments(review: Review): ReviewComment[] {
224	  return review.rounds.flatMap((r) => r.comments)
225	}
226	
227	/** Past the highest id in the file, so a submitted comment's id is never handed out twice. */
228	function nextCommentId(review: Review): string {
229	  const highest = allComments(review).reduce((max, c) => Math.max(max, Number(c.id.slice(1)) || 0), 0)
230	  return `C${highest + 1}`
231	}
232	
233	/** Comments are one line in the file; a pasted paragraph keeps its words, not its line breaks. */
234	const oneLine = (text: string): string => text.replace(/\s+/g, ' ').trim()
235	
236	export function addComment(review: Review, target: string, text: string, itemText?: string): ReviewComment {
237	  const body = oneLine(text)
238	  if (!body) throw new Error('A comment needs text.')
239	  const comment: ReviewComment = {
240	    id: nextCommentId(review),
241	    target,
242	    text: body,
243	    ...(itemText ? { item: oneLine(itemText) } : {}),
244	  }
245	  openRound(review).comments.push(comment)
246	  return comment
247	}
248	
249	function requirePending(review: Review, id: string): { round: ReviewRound; index: number } {
250	  const round = pendingRound(review)
251	  const index = round?.comments.findIndex((c) => c.id === id) ?? -1
252	  if (!round || index === -1) throw new Error(`Comment ${id} is submitted and cannot be changed.`)
253	  return { round, index }
254	}
255	
256	export function editComment(review: Review, id: string, text: string): void {
257	  const body = oneLine(text)
258	  if (!body) throw new Error('A comment needs text.')
259	  const { round, index } = requirePending(review, id)
260	  round.comments[index]!.text = body
261	}
262	
263	export function removeComment(review: Review, id: string): void {
264	  const { round, index } = requirePending(review, id)
265	  round.comments.splice(index, 1)
266	  prune(review)
267	}
268	
269	/** A round with nothing in it is not a round; it appears again on the next comment. */
270	function prune(review: Review): void {
271	  const round = pendingRound(review)
272	  if (round && round.comments.length === 0 && round.strikes.length === 0) review.rounds.pop()
273	}
274	
275	export function strikeItem(review: Review, itemId: string): void {
276	  if (struckItems(review).includes(itemId)) return
277	  openRound(review).strikes.push(itemId)
278	}
279	
280	/** Only an unsubmitted strike can be taken back; a struck item stays removed (B2, B9). */
281	export function unstrikeItem(review: Review, itemId: string): void {
282	  const round = pendingRound(review)
283	  if (!round?.strikes.includes(itemId)) throw new Error(`${itemId} is already struck in a submitted round.`)
284	  round.strikes = round.strikes.filter((s) => s !== itemId)
285	  prune(review)
286	}
287	
288	/** Every item ever struck, submitted or not. */
289	export function struckItems(review: Review): string[] {
290	  return [...new Set(review.rounds.flatMap((r) => r.strikes))]
291	}
