1	import { readFile, writeFile } from 'node:fs/promises'
2	
3	export type SpecStatus = 'draft' | 'approved'
4	
5	/** `body` is the markdown after the front matter, what a reader should see. */
6	export type SpecState = { exists: false } | { exists: true; status: SpecStatus; body: string }
7	
8	const FRONT_MATTER = /^---\r?\n([\s\S]*?)\r?\n---(\r?\n|$)/
9	
10	/**
11	 * The spec's front-matter `status` is the approval gate: phase 2 refuses a
12	 * draft, and a human sets `approved`. Held in the file so it survives
13	 * reloads and is visible in git.
14	 */
15	export async function readSpecState(path: string): Promise<SpecState> {
16	  let text: string
17	  try {
18	    text = await readFile(path, 'utf8')
19	  } catch (error) {
20	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return { exists: false }
21	    throw error
22	  }
23	  return { exists: true, status: statusOf(text), body: bodyOf(text) }
24	}
25	
26	export function bodyOf(text: string): string {
27	  return text.replace(FRONT_MATTER, '').replace(/^\s+/, '')
28	}
29	
30	export function statusOf(text: string): SpecStatus {
31	  const match = FRONT_MATTER.exec(text)
32	  const line = match?.[1]?.split(/\r?\n/).find((l) => /^status:/.test(l))
33	  return line?.slice('status:'.length).trim() === 'approved' ? 'approved' : 'draft'
34	}
35	
36	export async function setSpecStatus(path: string, status: SpecStatus): Promise<void> {
37	  const text = await readFile(path, 'utf8')
38	  await writeFile(path, withStatus(text, status), 'utf8')
39	}
40	
41	export function withStatus(text: string, status: SpecStatus): string {
42	  const match = FRONT_MATTER.exec(text)
43	  if (!match) return `---\nstatus: ${status}\n---\n\n${text}`
44	  const body = match[1]!
45	  const lines = body.split(/\r?\n/)
46	  const index = lines.findIndex((l) => /^status:/.test(l))
47	  if (index === -1) lines.push(`status: ${status}`)
48	  else lines[index] = `status: ${status}`
49	  return text.replace(FRONT_MATTER, `---\n${lines.join('\n')}\n---${match[2]}`)
50	}
