export const IMPLEMENT_KICKOFF = 'Implement the spec, task by task.'

export const TASKS_SECTION = 'Tasks'

/** `blocked` is unfinished work with a reason, not a finish; only `done` is a finish. */
export type TaskState = 'open' | 'done' | 'blocked'

export type Task = { id: string; text: string; state: TaskState }

const DONE = /\[done\]/i
const BLOCKED = /\[blocked\b/i

/**
 * The spec's task board, as the implementer leaves it. Task state is not held
 * anywhere else: the markers in the file are what survives a fresh session.
 */
export function tasks(body: string): Task[] {
  return planItems(body)
    .filter((item) => item.section === TASKS_SECTION && !item.removed)
    .map((item) => ({
      id: item.id,
      text: item.text,
