  it('counts_only_the_tasks_section_so_a_done_behaviour_is_not_a_task', () => {
    expect(tasks('## Behaviour\n- B1: something [done]\n')).toEqual([])
    expect(specDone('## Behaviour\n- B1: something [done]\n')).toBe(false)
  })

  it('is_done_only_when_every_task_is_done', () => {
    expect(specDone(board('- T1: a [done]', '- T2: b [done]'))).toBe(true)
    expect(specDone(board('- T1: a [done]', '- T2: b'))).toBe(false)
    // Blocked is unfinished work with a reason: there is still something to come back to.
    expect(specDone(board('- T1: a [done]', '- T2: b [blocked: needs a decision]'))).toBe(false)
    // A spec with no tasks at all is not vacuously finished.
    expect(specDone(board())).toBe(false)
  })

  it('refuses_to_start_again_on_a_spec_whose_every_task_is_done', () => {
    const done = board('- T1: a [done]', '- T2: b [done]')
    expect(() => assertImplementable({ exists: true, status: 'approved', body: done })).toThrow(/every task/i)
    // A blocked task is work left, so a fresh session is allowed to pick it up.
    const blocked = board('- T1: a [done]', '- T2: b [blocked: needs a decision]')
    expect(() => assertImplementable({ exists: true, status: 'approved', body: blocked })).not.toThrow()
    // Adding a task to a finished spec makes it unfinished again, with nothing to reset.
    expect(() => assertImplementable({ exists: true, status: 'approved', body: `${done}- T3: c\n` })).not.toThrow()
  })
